response_text:
{
  "case_id": "C08",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook: the body remembers",
      "narration": "Once you recover from an infection, your immune system doesn't forget it. Some of the T cells that fought the infection stick around as a memory population, ready for next time.",
      "on_screen": "A virus particle fades out; a small group of T cells remains on screen, labelled 'memory T cells'.",
      "claim_refs": ["SYN-C08:background"]
    },
    {
      "beat": "How long memory lasts",
      "narration": "A review of 302 adults measured how long that memory lasts for one specific viral target. Memory CD8 T cells were still detectable in 88 percent of people after five years, and in 61 percent after twelve.",
      "on_screen": "Bar chart: 88% at 5 years, 61% at 12 years, with confidence intervals 84-91 and 55-67.",
      "claim_refs": ["SYN-C08:results:5y-88pct", "SYN-C08:results:12y-61pct", "SYN-C08:stats:binomial-CI"]
    },
    {
      "beat": "The speed advantage",
      "narration": "And when those people met the virus again, their immune response ramped up 4.2 times faster than the first time around.",
      "on_screen": "Two response curves side by side: a slow primary rise, a steep secondary rise, tagged '4.2x faster'.",
      "claim_refs": ["SYN-C08:results:secondary-expansion-4.2x"]
    },
    {
      "beat": "The filing-cabinet analogy",
      "narration": "People often explain this like a filing cabinet: your body keeps a folder on every germ it has met, so it can pull it out fast.",
      "on_screen": "Animated filing cabinet; a drawer opens and a labelled folder slides out.",
      "claim_refs": ["SYN-C08:teaching-note:analogy"]
    },
    {
      "beat": "Where the analogy breaks",
      "narration": "That works for speed, but only for speed. Immune memory isn't indexed, nothing looks a file up on demand, and the folders fade with time, as those five and twelve year numbers show. Having memory cells also doesn't guarantee you won't get sick.",
      "on_screen": "The filing cabinet dissolves; three struck-through captions appear: 'not indexed', 'not permanent', 'not a guarantee of protection'.",
      "claim_refs": ["SYN-C08:teaching-note:breakdown", "SYN-C08:results:5y-88pct", "SYN-C08:results:12y-61pct"]
    },
    {
      "beat": "Why it matters",
      "narration": "These figures come from one viral target and vary between pathogens and people, but knowing how memory fades is exactly what helps scientists decide when a booster is due.",
      "on_screen": "Vaccine schedule timeline with booster markers; footnote: 'one defined viral epitope; varies by pathogen and individual'.",
      "claim_refs": ["SYN-C08:limitations", "SYN-C08:discussion"]
    }
  ]
}
